    27  /*
    28   * Parse JSON object serialization format (RFC-7159)
    29   */
    30
    31  #ifndef TEST
    32  #include "file.h"
    33
    34  #ifndef lint
    35  FILE_RCSID("@(#)$File: is_json.c,v 1.24 2022/07/04 20:08:07 christos Exp $")
    36  #endif
    37
    38  #include "magic.h"
    39  #else
    40  #include <stdio.h>
    41  #include <stddef.h>
    42  #endif
    43  #include <string.h>
    44
    45  #ifdef DEBUG
    46  #include <stdio.h>
    47  #define DPRINTF(a, b, c)        \
    48      printf("%*s%s [%.2x/%c] %.*s\n", (int)lvl, "", (a), *(b), *(b), \
    49          (int)(b - c), (const char *)(c))
    50  #define __file_debugused
    51  #else
    52  #define DPRINTF(a, b, c)        do { } while (/*CONSTCOND*/0)
    53  #define __file_debugused __attribute__((__unused__))
    54  #endif
    55
    56  #define JSON_ARRAY      0
    57  #define JSON_CONSTANT   1
    58  #define JSON_NUMBER     2
    59  #define JSON_OBJECT     3
    60  #define JSON_STRING     4
    61  #define JSON_ARRAYN     5
    62  #define JSON_MAX        6
    63
    64  /*
    65   * if JSON_COUNT != 0:
    66   *      count all the objects, require that we have the whole data file
    67   * otherwise:
    68   *      stop if we find an object or an array
    69   */
    70  #ifndef JSON_COUNT
    71  #define JSON_COUNT 0
    72  #endif
    73
    74  static int json_parse(const unsigned char **, const unsigned char *, size_t *,
    75          size_t);
    76
    77  static int
    78  json_isspace(const unsigned char uc)
    79  {
    80          switch (uc) {
    81          case ' ':
    82          case '\n':
    83          case '\r':
    84          case '\t':
    85                  return 1;
    86          default:
    87                  return 0;
    88          }
    89  }
    90
    91  static int
    92  json_isdigit(unsigned char uc)
    93  {
    94          switch (uc) {
    95          case '0': case '1': case '2': case '3': case '4':
    96          case '5': case '6': case '7': case '8': case '9':
    97                  return 1;
    98          default:
    99                  return 0;
   100          }
   101  }
   102
   103  static int
   104  json_isxdigit(unsigned char uc)
   105  {
   106          if (json_isdigit(uc))
   107                  return 1;
   108          switch (uc) {
   109          case 'a': case 'b': case 'c': case 'd': case 'e': case 'f':
   110          case 'A': case 'B': case 'C': case 'D': case 'E': case 'F':
   111                  return 1;
   112          default:
   113                  return 0;
   114          }
   115  }
   116
   117  static const unsigned char *
   118  json_skip_space(const unsigned char *uc, const unsigned char *ue)
   119  {
   120          while (uc < ue && json_isspace(*uc))
   121                  uc++;
   122          return uc;
   123  }
   124
   125  static int
   126  json_parse_string(const unsigned char **ucp, const unsigned char *ue,
   127      size_t lvl __file_debugused)
   128  {
   129          const unsigned char *uc = *ucp;
   130          size_t i;
   131
   132          DPRINTF("Parse string: ", uc, *ucp);
   133          while (uc < ue) {
   134                  switch (*uc++) {
   135                  case '\0':
   136                          goto out;
   137                  case '\\':
   138                          if (uc == ue)
   139                                  goto out;
   140                          switch (*uc++) {
   141                          case '\0':
   142                                  goto out;
   143                          case '"':
   144                          case '\\':
   145                          case '/':
   146                          case 'b':
   147                          case 'f':
   148                          case 'n':
   149                          case 'r':
   150                          case 't':
   151                                  continue;
   152                          case 'u':
   153                                  if (ue - uc < 4) {
   154                                          uc = ue;
   155                                          goto out;
   156                                  }
   157                                  for (i = 0; i < 4; i++)
   158                                          if (!json_isxdigit(*uc++))
   159                                                  goto out;
   160                                  continue;
   161                          default:
   162                                  goto out;
   163                          }
   164                  case '"':
   165                          DPRINTF("Good string: ", uc, *ucp);
   166                          *ucp = uc;
   167                          return 1;
   168                  default:
   169                          continue;
   170                  }
   171          }
   172  out:
   173          DPRINTF("Bad string: ", uc, *ucp);
   174          *ucp = uc;
   175          return 0;
   176  }
   177
   178  static int
   179  json_parse_array(const unsigned char **ucp, const unsigned char *ue,
   180          size_t *st, size_t lvl)
   181  {
   182          const unsigned char *uc = *ucp;
   183
   184          DPRINTF("Parse array: ", uc, *ucp);
   185          while (uc < ue) {
   186                  uc = json_skip_space(uc, ue);
   187                  if (uc == ue)
   188                          goto out;
   189                  if (*uc == ']')
   190                          goto done;
   191                  if (!json_parse(&uc, ue, st, lvl + 1))
   192                          goto out;
   193                  if (uc == ue)
   194                          goto out;
   195                  switch (*uc) {
   196                  case ',':
   197                          uc++;
   198                          continue;
   199                  case ']':
   200                  done:
   201                          st[JSON_ARRAYN]++;
   202                          DPRINTF("Good array: ", uc, *ucp);
   203                          *ucp = uc + 1;
   204                          return 1;
   205                  default:
   206                          goto out;
   207                  }
   208          }
   209  out:
   210          DPRINTF("Bad array: ", uc,  *ucp);
   211          *ucp = uc;
   212          return 0;
   213  }
   214
   215  static int
   216  json_parse_object(const unsigned char **ucp, const unsigned char *ue,
   217          size_t *st, size_t lvl)
   218  {
   219          const unsigned char *uc = *ucp;
   220          DPRINTF("Parse object: ", uc, *ucp);
   221          while (uc < ue) {
   222                  uc = json_skip_space(uc, ue);
   223                  if (uc == ue)
   224                          goto out;
   225                  if (*uc == '}') {
   226                          uc++;
   227                          goto done;
   228                  }
   229                  if (*uc++ != '"') {
   230                          DPRINTF("not string", uc, *ucp);
   231                          goto out;
   232                  }
   233                  DPRINTF("next field", uc, *ucp);
   234                  if (!json_parse_string(&uc, ue, lvl)) {
   235                          DPRINTF("not string", uc, *ucp);
   236                          goto out;
   237                  }
   238                  uc = json_skip_space(uc, ue);
   239                  if (uc == ue)
   240                          goto out;
   241                  if (*uc++ != ':') {
   242                          DPRINTF("not colon", uc, *ucp);
   243                          goto out;
   244                  }
   245                  if (!json_parse(&uc, ue, st, lvl + 1)) {
   246                          DPRINTF("not json", uc, *ucp);
   247                          goto out;
   248                  }
   249                  if (uc == ue)
   250                          goto out;
   251                  switch (*uc++) {
   252                  case ',':
   253                          continue;
   254                  case '}': /* { */
   255                  done:
   256                          DPRINTF("Good object: ", uc, *ucp);
   257                          *ucp = uc;
   258                          return 1;
   259                  default:
   260                          DPRINTF("not more", uc, *ucp);
